mapper.select:
SELECT DISTINCT i.GUID AS GUID, i.ID AS ITEMID, n.ID AS FILEID, f.GUID AS FILEGUID, n.NAME FILEOBJECT, n.REVISIONID || '.' || n.ITERATIONID AS FILEREVISIONID, f.NAME AS FILEUINAME, f.FILEPATH AS FILEPATH, f.ID AS FILEENTITYNAME, f.FILETYPE AS FILETYPE FROM VIEWOBJECT_0 v, ITEM_0 i, NT_00094_0 s, NT_00029_0 n, BI_FILE f WHERE v.GUID = s.VIEWFK AND v.END1$MASTER = i.MASTERFK AND s.END2$MASTER = n.MASTERFK AND n.GUID = f.REVISIONGUID AND n.ITERATIONID=f.ITERATIONID AND i.LATESTREVISION LIKE '%m%' AND n.LATESTREVISION LIKE '%m%' AND ROWNUM=1
AND f.GUID = #{fileGuid}
AND i.ID = #{fileitemid}
